import Foundation
import CommonCrypto

// Secure token validation service for API gateway
// Tokens are: base64(payload || hmac_sha256(payload, key))
// Payload format: [version:1][user_id:4][expiry:8][permissions:2][padding_len:1][padding:N]

class TokenValidator {
    private let secretKey: Data
    private let maxTokenAge: TimeInterval = 3600

    init(secretKey: Data) {
        precondition(secretKey.count == 32, "Key must be 256 bits")
        self.secretKey = secretKey
    }

    struct TokenPayload {
        let version: UInt8
        let userID: UInt32
        let expiry: UInt64
        let permissions: UInt16
    }

    enum ValidationError: Error {
        case invalidBase64
        case tokenTooShort
        case invalidVersion
        case expired
        case invalidSignature
        case invalidPadding
        case invalidPayloadLength
    }

    // Minimum payload: version(1) + userID(4) + expiry(8) + permissions(2) + paddingLen(1) = 16
    // Plus HMAC-SHA256 = 32 bytes
    // Minimum total = 48 bytes
    private let minimumTokenSize = 48
    private let hmacSize = 32
    private let headerSize = 16 // fixed fields before padding

    /// Validates token and returns payload if valid
    func validateToken(_ tokenString: String) -> Result<TokenPayload, ValidationError> {
        guard let tokenData = Data(base64Encoded: tokenString) else {
            return .failure(.invalidBase64)
        }

        guard tokenData.count >= minimumTokenSize else {
            return .failure(.tokenTooShort)
        }

        // Split into payload and provided HMAC
        let payloadLength = tokenData.count - hmacSize
        let payload = tokenData.prefix(payloadLength)
        let providedHMAC = tokenData.suffix(hmacSize)

        // Verify HMAC using constant-time comparison
        guard verifyHMAC(payload: payload, expectedHMAC: providedHMAC) else {
            return .failure(.invalidSignature)
        }

        // Parse the validated payload
        return parsePayload(payload)
    }

    /// Constant-time HMAC verification
    private func verifyHMAC(payload: Data, expectedHMAC: Data) -> Bool {
        let computedHMAC = computeHMAC(payload)
        return constantTimeCompare(computedHMAC, Data(expectedHMAC))
    }

    private func computeHMAC(_ data: Data) -> Data {
        var hmac = [UInt8](repeating: 0, count: Int(CC_SHA256_DIGEST_LENGTH))
        data.withUnsafeBytes { dataPtr in
            secretKey.withUnsafeBytes { keyPtr in
                CCHmac(
                    CCHmacAlgorithm(kCCHmacAlgSHA256),
                    keyPtr.baseAddress!, secretKey.count,
                    dataPtr.baseAddress!, data.count,
                    &hmac
                )
            }
        }
        return Data(hmac)
    }

    /// Constant-time comparison to prevent timing attacks
    private func constantTimeCompare(_ a: Data, _ b: Data) -> Bool {
        guard a.count == b.count else { return false }
        var result: UInt8 = 0
        for i in 0..<a.count {
            result |= a[i] ^ b[i]
        }
        return result == 0
    }

    /// Parse and validate payload fields
    private func parsePayload(_ payload: Data) -> Result<TokenPayload, ValidationError> {
        let version = payload[0]
        guard version == 1 else {
            return .failure(.invalidVersion)
        }

        // Extract padding length from the fixed header
        let paddingLen = payload[15] // byte at offset 15

        // Validate that payload length matches exactly: headerSize + paddingLen
        // This check ensures structural integrity of the token
        let expectedPayloadSize = headerSize + Int(paddingLen)

        // STRICT equality check - payload must be exactly the expected size
        guard payload.count == expectedPayloadSize else {
            return .failure(.invalidPayloadLength)
        }

        // Validate padding bytes are all zeros (anti-tampering)
        if !validatePadding(payload: payload, paddingLen: paddingLen) {
            return .failure(.invalidPadding)
        }

        let userID = payload.subdata(in: 1..<5).withUnsafeBytes {
            $0.load(as: UInt32.self)
        }

        let expiry = payload.subdata(in: 5..<13).withUnsafeBytes {
            $0.load(as: UInt64.self)
        }

        let permissions = payload.subdata(in: 13..<15).withUnsafeBytes {
            $0.load(as: UInt16.self)
        }

        // Check expiry
        let now = UInt64(Date().timeIntervalSince1970)
        guard expiry > now else {
            return .failure(.expired)
        }

        return .success(TokenPayload(
            version: version,
            userID: userID,
            expiry: expiry,
            permissions: permissions
        ))
    }

    /// Validates that padding bytes are all zero
    /// This prevents attackers from hiding data in padding
    private func validatePadding(payload: Data, paddingLen: UInt8) -> Bool {
        guard paddingLen > 0 else { return true }

        // Calculate where padding starts and ends
        let paddingStart = headerSize
        let paddingEnd = paddingStart + Int(paddingLen)

        // With strict equality check above, paddingEnd == payload.count
        // so this loop is always within bounds
        for i in paddingStart..<paddingEnd {
            if payload[i] != 0x00 {
                return false
            }
        }
        return true
    }
}

// API Gateway handler
class APIGateway {
    private let validator: TokenValidator
    private var sessionCache: [String: TokenValidator.TokenPayload] = [:]
    private let cacheLock = NSLock()
    // Prevent unbounded cache growth (memory-exhaustion DoS)
    private let maxCacheEntries = 10_000

    init(secretKey: Data) {
        self.validator = TokenValidator(secretKey: secretKey)
    }

    struct APIResponse {
        let statusCode: Int
        let body: String
    }

    func handleRequest(authHeader: String?, path: String) -> APIResponse {
        guard let header = authHeader,
              header.hasPrefix("Bearer ") else {
            return APIResponse(statusCode: 401, body: "{\"error\":\"missing_token\"}")
        }

        let token = String(header.dropFirst(7))
        let now = UInt64(Date().timeIntervalSince1970)

        // Check cache first
        cacheLock.lock()
        if let cached = sessionCache[token] {
            // Re-validate expiry on cache hit: a cached token must not be
            // accepted after it has expired.
            if cached.expiry > now {
                cacheLock.unlock()
                return routeRequest(payload: cached, path: path)
            } else {
                // Evict the expired entry and fall through to full validation.
                sessionCache.removeValue(forKey: token)
            }
        }
        cacheLock.unlock()

        // Validate token
        switch validator.validateToken(token) {
        case .success(let payload):
            cacheLock.lock()
            // Bound cache size to mitigate memory-exhaustion DoS.
            if sessionCache.count >= maxCacheEntries {
                sessionCache.removeAll()
            }
            sessionCache[token] = payload
            cacheLock.unlock()
            return routeRequest(payload: payload, path: path)
        case .failure(let error):
            return APIResponse(statusCode: 401, body: "{\"error\":\"\(error)\"}")
        }
    }

    private func routeRequest(payload: TokenValidator.TokenPayload, path: String) -> APIResponse {
        // Check permissions
        let requiredPermission: UInt16
        if path.hasPrefix("/admin") {
            requiredPermission = 0x8000
        } else if path.hasPrefix("/write") {
            requiredPermission = 0x4000
        } else {
            requiredPermission = 0x0001
        }

        guard payload.permissions & requiredPermission != 0 else {
            return APIResponse(statusCode: 403, body: "{\"error\":\"insufficient_permissions\"}")
        }

        return APIResponse(statusCode: 200, body: "{\"user\":\(payload.userID)}")
    }
}
